package com.suarez.empleados; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*; import java.util.concurrent.atomic.AtomicLong; @RestController @RequestMapping("/empleados") public class EmpleadoController { private final Map<Long,Empleado> db=new LinkedHashMap<>(); private final AtomicLong seq=new AtomicLong(); @PostMapping @ResponseStatus(HttpStatus.CREATED) public Empleado crear(@Valid @RequestBody Empleado e){long id=seq.incrementAndGet();var n=new Empleado(id,e.nombres(),e.apellidos(),e.email(),e.sueldo());db.put(id,n);return n;} @GetMapping public Collection<Empleado> listar(){return List.copyOf(db.values());} @GetMapping("/{id}") public Empleado obtener(@PathVariable long id){return required(id);} @PutMapping("/{id}") public Empleado actualizar(@PathVariable long id,@Valid @RequestBody Empleado e){required(id);var n=new Empleado(id,e.nombres(),e.apellidos(),e.email(),e.sueldo());db.put(id,n);return n;} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void borrar(@PathVariable long id){if(db.remove(id)==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);} private Empleado required(long id){var e=db.get(id);if(e==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Empleado no encontrado");return e;} }
